import { Game, makeCommandGroup, makeInfantry, makeVehicle, makeMachineGunTeam, type Terrain } from "../../engine/index.js";
import type { Scenario, ScenarioListing } from "./types.js";
import { TEL_AZEKA } from "../maps/telAzeka.js";
