/**
 * Tel Azeka over the Elah valley (תל עזקה, עמק האלה): the tel stands at 345 m in the middle of the window, its eastern face falling 110 m to the valley floor, a ridge running south from it and low ground in the east.
 * 1200 × 1000 m centred on 31.69850 N, 34.93550 E, north up.
 */
export function buildTelAzekaDelayTerrain(): Terrain {
  return { heightfield: TEL_AZEKA, objects: TEL_AZEKA_OBJECTS, roads: TEL_AZEKA_ROADS };
}

/**
 * A delay on Tel Azeka (decision 109, the author, 2026-10-21): the scenario for
 * telling whether breaking contact pays where holding loses. One RED squad of
 * telAzekaAssault's platoon, dug in where it stood there (RED-A-2), against one
 * BLUE platoon of that battle (BLUE-2: three squads, two machine gun teams, its
 * headquarters), from where it stood. No indirect fire, no charges. RED's
 * mission is a delay: not beaten by the end of turn 15, it has achieved it,
 * whatever ground it gave (ATP 3-06.11 (2024), para 4-130).
 *
 * ⚠️ Ours: the cut-down forces, and turn 15, which is also the attack's deadline
 * (telAzekaAssault's battles run a median of 12-13 turns).
 */
export function buildTelAzekaDelayScenario(seed = 1967): Scenario {
  const game = new Game({
    seed,
    trackIntel: true,
    enforceC2: true,
    morale: true,
    locationError: true,
    stillDetection: true,
    binoculars: true,
    keepEyesOn: true,
    commandSuccession: true,
    delayUntil: 15,
    attackers: ["BLUE"],
    commandEchelon: { BLUE: "platoon", RED: "platoon" },
    // The defender's reinforcement (rules decision 122): written by the tool from the spec.
    reinforcements: [{ side: "RED", window: [5, 10], units: [makeInfantry("RED-REINF-1", "RED", "team", { x: 650, y: 10 }, 4, "תגבורת 1")] }],
    terrain: buildTelAzekaDelayTerrain(),
  });

  game.addUnit(makeCommandGroup("BLUE-2-HQ", "BLUE", "platoon", { x: 640, y: 975 }, 3, "חפ\"ק מ\"מ 2"));
  game.addUnit(makeInfantry("BLUE-2-1", "BLUE", "squad", { x: 580, y: 930 }, 8, "כיתה 2/1"));
  game.addUnit(makeInfantry("BLUE-2-2", "BLUE", "squad", { x: 650, y: 925 }, 8, "כיתה 2/2"));
  game.addUnit(makeInfantry("BLUE-2-3", "BLUE", "squad", { x: 720, y: 935 }, 8, "כיתה 2/3"));
  game.addUnit(makeMachineGunTeam("BLUE-2-MG1", "BLUE", { x: 600, y: 930 }, 3, "חולית מקלע 1/2"));
  game.addUnit(makeMachineGunTeam("BLUE-2-MG2", "BLUE", { x: 700, y: 935 }, 3, "חולית מקלע 2/2"));
  // Dressed before it is added: addUnit records a force as it stands, so
  // a force camouflaged or covered after the fact would replay undressed.
  const reda2 = makeInfantry("RED-A-2", "RED", "squad", { x: 650, y: 520 }, 8, "מחלקה א'/2");
  reda2.baseCover = "full";
  reda2.front = 91;
  game.addUnit(reda2);

  return { game, mapWidth: 1200, mapHeight: 1000, title: "תל עזקה — עיכוב" };
}

